import{sensesTasks,validSenses}from './senses-models.js?v=20261023-physicscomplete01';import{showSenses}from './senses-visuals.js?v=20261023-physicscomplete01';export{showSenses};
export function mountSenses(l,p,root,{save,done,feedback}){let ts=sensesTasks[l.widget.slice(7)],w=p.widget;w.sensesTask??=0;w.sensesPassed??=[];w.sensesDrafts??={};let i=Math.min(w.sensesTask,ts.length-1),t=ts[i],v=w.sensesDrafts[i]??={case:0,answer:'',seen:[]},c=t.cases[v.case],$=s=>root.querySelector(s),field=(id,label,opts,val)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${opts.map((x,j)=>`<option value="${j}" ${String(j)===String(val)?'selected':''}>${x}</option>`).join('')}</select>`,remount=()=>mountSenses(l,p,root,{save,done,feedback});
root.innerHTML=`<p class="activity-count">${i+1} / ${ts.length} · ${t.title}</p>`+field('sensesCase','Scenario',t.cases.map(c=>c[1]),v.case)+field('sensesAnswer','Predict and explain',c[2],v.answer)+'<button class="secondary" id="revealSenses">Reveal evidence →</button><p id="sensesReadout" aria-live="polite"></p><p id="sensesSeen"></p><div class="lab-actions"><button class="secondary" id="recordSenses">Record reasoning</button><button class="secondary" id="nextSenses">Next challenge →</button></div><p id="sensesProgress"></p>';
const draw=()=>{let revealed=v.revealed===v.case;showSenses(t.kind,{state:c[0],concealed:!revealed,corrected:t.kind==='vision'&&revealed,title:t.title,label:c[1]});$('#sensesReadout').textContent=revealed?c[4]:'Predict before revealing.';$('#sensesSeen').textContent=t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · ');$('#sensesProgress').textContent=w.sensesPassed.length+' / '+ts.length+' complete';};draw();
$('#sensesCase').onchange=e=>{if(e.target.value==='')return;v.case=Number(e.target.value);v.answer='';delete v.revealed;save();remount();};$('#sensesAnswer').onchange=e=>{v.answer=e.target.value;save();};$('#revealSenses').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validSenses(c,v.answer)?'Prediction agrees. Record the evidence.':c[4],!validSenses(c,v.answer));};$('#recordSenses').onclick=()=>{if(v.revealed!==v.case||!validSenses(c,v.answer)){feedback(c[4]+' Correct your prediction and reveal the evidence before recording.',true);return;}if(!v.seen.includes(v.case))v.seen.push(v.case);if(v.seen.length===t.cases.length&&!w.sensesPassed.includes(i))w.sensesPassed.push(i);if(w.sensesPassed.length===ts.length){p.widgetDone=true;done();}save();draw();feedback(v.seen.length===t.cases.length?'Challenge recorded.':'Recorded. Compare the other scenarios.');};$('#nextSenses').onclick=()=>{if(!w.sensesPassed.includes(i)){feedback('Complete every scenario in this challenge first.',true);return;}w.sensesTask=(i+1)%ts.length;save();remount();};}
